// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/// @title RUNNER — the run-to-earn token of the RUNNER app.
/// @notice Fixed supply of 1,000,000,000 RUNNER, all created at deployment:
///         • 80% run rewards — held by this contract, paid out only through claim()
///         • 10% liquidity   — to the RunnerHook, which locks it forever in the RUNNER/IMD
///                             Uniswap v4 pool (it can never be removed)
///         • 10% team        — to the team wallet
///         There is no mint function. Supply can only go down (burn).
///
///         This token has no transfer tax: every transfer moves exactly the amount sent.
///         The 4% trading fee is charged by the RunnerHook on the IMD side of every swap in
///         the RUNNER/IMD pool, so it is paid in IMD:
///         • 2% to the protocol wallet (sent by the hook)
///         • 2% to holders, delivered to this contract in IMD. Each UTC day's holder IMD is
///           shared by every wallet that held at least 300,000 RUNNER for that whole day, in
///           proportion to the lowest balance it held that day. A day's share can be claimed
///           for 7 days after the day ends; whatever is left after that goes to the protocol
///           wallet (sweepExpired).
///
/// @dev    Holder rewards use per-wallet daily checkpoints {day, lowest balance that day,
///         balance at the end of the day} and a running total of eligible balances, so
///         nothing ever loops over holders. Run rewards: the RUNNER server signs an EIP-712
///         message "account has earned `totalEarned` in total"; claim() pays the difference
///         to what was already claimed, limited by the emission schedule (launch: 10M/day,
///         halving every 30 days, floor 100k/day; the owner can change it from the next day,
///         never above 20M/day). The owner cannot change the tax, mint, or take tokens
///         out of the holder-reward bucket. Run rewards leave the pool only through signed
///         claims, at most the day's emission — but the owner chooses the signer, so a
///         compromised owner key could claim up to that daily cap: use a multisig owner.
///         The 300,000 threshold applies per address: tokens pooled in a vault or wrapper
///         count as one holder. Only trades through the RunnerHook pool pay the fee; other
///         pools someone may create are untaxed (the owner can exclude them from rewards).
contract RunnerToken {
    string public constant name = "RUNNER";
    string public constant symbol = "RUNNER";
    uint8 public constant decimals = 18;

    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    uint256 public constant REWARDS_ALLOCATION = 800_000_000 ether;
    uint256 public constant LIQUIDITY_ALLOCATION = 100_000_000 ether;
    uint256 public constant TEAM_ALLOCATION = 100_000_000 ether;

    uint256 public constant MIN_HOLDING = 300_000 ether;
    uint256 public constant CLAIM_WINDOW_DAYS = 7;
    /// Run-reward emission: starts at 10,000,000 RUNNER/day, halving every 30 days, never
    /// below 100,000/day. The owner can set a new schedule, which starts the next UTC day,
    /// but never above MAX_DAILY_EMISSION — so even a stolen owner key can move at most
    /// 2.5% of the pool per UTC day. The cap resets at 00:00 UTC, so two days' worth can be
    /// claimed seconds apart across midnight (worst case 5% within 24 hours; fifth audit, #9).
    uint256 public constant MAX_DAILY_EMISSION = 20_000_000 ether;
    uint256 public constant MIN_HALVING_DAYS = 7;
    uint256 public constant MAX_HALVING_DAYS = 3650;
    /// Run-reward payout choice: take it now and 20% is burned, or lock it 7 days for 100%.
    uint256 public constant INSTANT_BURN_BPS = 2_000;
    uint256 public constant LOCK_PERIOD = 7 days;
    uint256 public constant MAX_ACTIVE_LOCKS = 30;
    uint256 private constant BPS = 10_000;
    address private constant DEAD = 0x000000000000000000000000000000000000dEaD;

    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 public constant CLAIM_TYPEHASH =
        keccak256("Claim(address account,uint256 totalEarned,uint256 deadline,bool instant)");
    uint256 private constant HALF_ORDER = 0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;

    struct Checkpoint {
        uint32 day;          // UTC day number (timestamp / 1 days)
        uint112 minBalance;  // lowest balance held during `day`
        uint112 endBalance;  // balance after the last change on `day`
    }

    struct Lock {
        uint128 amount;
        uint64 unlockAt;
    }

    struct Schedule {
        uint128 dailyStart;   // RUNNER/day on fromDay
        uint128 floor;        // never below this
        uint32 halvingDays;   // halves every this many days
        uint32 fromDay;       // UTC day the schedule (and its halving clock) begins
    }

    struct Day {
        uint256 shares;      // sum of eligible lowest balances for the day
        uint128 rewards;     // holder rewards (IMD) received during the day
        uint128 paidOut;     // claimed by holders + swept to the protocol
        bool started;
    }

    uint256 public totalSupply;
    address public owner;
    address public pendingOwner;         // two-step handover: set by the owner, accepted by the new owner
    address public protocolWallet;
    address public signer;
    bool public claimsPaused;
    uint256 public emissionStartDay;     // 0 = emission not started yet
    Schedule private _schedule = Schedule(uint128(10_000_000 ether), uint128(100_000 ether), 30, 0);
    Schedule private _nextSchedule;      // fromDay = 0 → none pending
    uint256 public totalClaimed;
    uint256 public totalLocked;          // locked run rewards inside this contract
    uint256 public totalBurnedInstant;   // burned by instant claims / early releases

    uint256 public eligibleSupply;       // sum of balances >= MIN_HOLDING of non-excluded wallets
    uint256 public holderRewardsHeld;    // IMD inside this contract owed to holders (not yet paid out)
    uint256 public totalHolderRewards;   // all IMD ever received for holders
    uint256 public nextSweepDay;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public claimed;
    mapping(uint256 => uint256) public claimedOnDay;
    mapping(address => bool) public excludedFromHolderRewards;
    mapping(address => Checkpoint[]) private _checkpoints;
    mapping(uint256 => Day) private _days;
    mapping(address => mapping(uint256 => bool)) public holderClaimedDay;
    mapping(address => Lock[]) private _locks;      // in unlock order
    mapping(address => uint256) private _lockHead;  // first lock not yet paid out

    uint256 private immutable _cachedChainId;
    bytes32 private immutable _cachedDomainSeparator;
    /// @notice Holder rewards are paid in this token (IMD).
    address public immutable rewardToken;
    /// @notice The RunnerHook that owns the RUNNER/IMD pool and sends the holder IMD here.
    address public immutable hook;
    /// @notice The Uniswap v4 PoolManager that holds the pool's tokens (excluded from rewards).
    address public immutable poolManager;
    uint256 private _locked = 1;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed holder, address indexed spender, uint256 value);
    event Claimed(address indexed account, uint256 amount, uint256 totalEarned, bool instant);
    event RewardsLocked(address indexed account, uint256 amount, uint256 unlockAt);
    event RewardsReleased(address indexed account, uint256 amount);
    event RewardsBurned(address indexed account, uint256 amount);
    event HolderRewardsAdded(uint256 indexed day, uint256 amount);
    event HolderRewardsClaimed(address indexed holder, uint256 amount);
    event HolderRewardsExpired(uint256 indexed day, uint256 amount);
    event PoolExcluded(address indexed pool);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event ProtocolWalletChanged(address indexed wallet);
    event SignerChanged(address indexed signer);
    event ClaimsPausedChanged(bool paused);
    event EmissionStarted(uint256 day);
    event EmissionScheduleSet(uint256 dailyStart, uint256 halvingDays, uint256 floor, uint256 fromDay);

    error NotOwner();
    error ZeroAddress();
    error InsufficientBalance();
    error InsufficientAllowance();
    error ClaimsPaused();
    error Expired();
    error BadSignature();
    error NothingToClaim();
    error DailyCapReached();
    error PoolEmpty();
    error OnlyRunnerCanClaimInstantly();
    error TooManyLocks();
    error NothingToRelease();
    error NotAContract();
    error AlreadyExcluded();
    error BadAddress();
    error Reentrancy();
    error TransferFailed();
    error NotAPool();
    error EmissionNotStarted();
    error AlreadyStarted();
    error BadSchedule();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    /// @param hook_ the RunnerHook (deployed first); it receives the liquidity allocation and locks it in the pool
    constructor(address initialOwner, address hook_, address teamWallet, address rewardToken_, address poolManager_) {
        if (initialOwner == address(0) || hook_ == address(0) || teamWallet == address(0) || rewardToken_ == address(0) || poolManager_ == address(0)) revert ZeroAddress();
        // The owner is also the first protocol wallet: same rule as setProtocolWallet (sixth audit, #1).
        if (initialOwner == address(this) || initialOwner == poolManager_ || initialOwner == hook_) revert BadAddress();
        rewardToken = rewardToken_;
        hook = hook_;
        poolManager = poolManager_;
        owner = initialOwner;
        protocolWallet = initialOwner;
        emit OwnershipTransferred(address(0), initialOwner);
        emit ProtocolWalletChanged(initialOwner);
        _cachedChainId = block.chainid;
        _cachedDomainSeparator = _buildDomainSeparator();

        // The pool's tokens sit in the PoolManager; the hook only holds them until the pool opens.
        excludedFromHolderRewards[address(this)] = true;
        excludedFromHolderRewards[hook_] = true;
        excludedFromHolderRewards[poolManager_] = true;
        excludedFromHolderRewards[DEAD] = true;
        uint256 today = _today();
        nextSweepDay = today;
        // Opening balances count as held for the whole deploy day, then the day's share
        // total is frozen — so launch-day holder tax goes to holders, not the protocol.
        _mintAtStart(address(this), REWARDS_ALLOCATION, today);
        _mintAtStart(hook_, LIQUIDITY_ALLOCATION, today);
        _mintAtStart(teamWallet, TEAM_ALLOCATION, today);
        _startDay(today);
    }

    // ----------------------------------------------------------------- ERC-20

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        _spendAllowance(from, value);
        _transfer(from, to, value);
        return true;
    }

    /// @notice Destroy your own tokens (used by in-app spending later).
    function burn(uint256 value) external {
        _burn(msg.sender, value);
    }

    function burnFrom(address from, uint256 value) external {
        _spendAllowance(from, value);
        _burn(from, value);
    }

    // ----------------------------------------------------------------- holder rewards

    /// @notice Holder rewards `holder` can claim right now (days ended within the last 7 days).
    function holderClaimable(address holder) public view returns (uint256 total) {
        uint256 today = _today();
        uint256 first = today > CLAIM_WINDOW_DAYS ? today - CLAIM_WINDOW_DAYS : 0;
        for (uint256 d = first; d < today; d++) {
            if (!holderClaimedDay[holder][d]) total += _holderShareOf(holder, d);
        }
    }

    /// @notice Claim all holder rewards still inside their 7-day window.
    function claimHolderRewards() external nonReentrant returns (uint256 total) {
        uint256 today = _today();
        uint256 first = today > CLAIM_WINDOW_DAYS ? today - CLAIM_WINDOW_DAYS : 0;
        for (uint256 d = first; d < today; d++) {
            if (holderClaimedDay[msg.sender][d]) continue;
            uint256 amount = _holderShareOf(msg.sender, d);
            if (amount == 0) continue;
            holderClaimedDay[msg.sender][d] = true;
            _days[d].paidOut += uint128(amount);
            total += amount;
        }
        if (total == 0) revert NothingToClaim();
        holderRewardsHeld -= total;
        emit HolderRewardsClaimed(msg.sender, total);
        _sendReward(msg.sender, total);
    }

    /// @notice Send unclaimed holder rewards of expired days (older than 7 days) to the
    ///         protocol wallet. Anyone may call; processes at most `maxDays` days.
    function sweepExpired(uint256 maxDays) external nonReentrant returns (uint256 total) {
        uint256 today = _today();
        uint256 d = nextSweepDay;
        uint256 end = maxDays > type(uint256).max - d ? type(uint256).max : d + maxDays; // max = "all" (fourth audit, #8)
        while (d + CLAIM_WINDOW_DAYS < today && d < end) {
            Day storage day = _days[d];
            uint256 left = uint256(day.rewards) - day.paidOut;
            if (left > 0) {
                day.paidOut = day.rewards;
                total += left;
                emit HolderRewardsExpired(d, left);
            }
            d++;
        }
        nextSweepDay = d;
        if (total > 0) {
            holderRewardsHeld -= total;
            _sendReward(protocolWallet, total);
        }
    }

    /// @notice Books IMD that arrived since the last call as today's holder rewards. The hook
    ///         calls it after sending the holder share; anyone may call it (IMD sent here by
    ///         anyone simply becomes holder rewards for today).
    function syncHolderRewards() public nonReentrant returns (uint256 amount) {
        uint256 bal = _rewardBalance();
        uint256 held = holderRewardsHeld;
        if (bal <= held) return 0;
        amount = bal - held;
        if (amount > type(uint128).max) amount = type(uint128).max;
        uint256 today = _today();
        _startDay(today);
        holderRewardsHeld = held + amount;
        totalHolderRewards += amount;
        _days[today].rewards += uint128(amount);
        emit HolderRewardsAdded(today, amount);
    }

    /// @notice A day's totals: eligible shares, holder IMD received, amount paid out.
    function dayInfo(uint256 day) external view returns (uint256 shares, uint256 rewards, uint256 paidOut) {
        Day storage d = _days[day];
        return (d.shares, d.rewards, d.paidOut);
    }

    /// @notice The balance that counts for `holder` on `day` (0 if under 300,000 or excluded).
    function eligibleBalanceOn(address holder, uint256 day) public view returns (uint256) {
        if (excludedFromHolderRewards[holder]) return 0;
        Checkpoint[] storage cps = _checkpoints[holder];
        uint256 lo = 0;
        uint256 hi = cps.length;
        while (lo < hi) {                       // first checkpoint with day > `day`
            uint256 mid = (lo + hi) / 2;
            if (cps[mid].day > day) hi = mid; else lo = mid + 1;
        }
        if (lo == 0) return 0;
        Checkpoint storage cp = cps[lo - 1];
        return _eligible(cp.day == day ? cp.minBalance : cp.endBalance);
    }

    function currentDay() external view returns (uint256) {
        return _today();
    }

    // ----------------------------------------------------------------- run rewards

    /// @notice RUNNER still waiting in the run-reward pool.
    function rewardsRemaining() public view returns (uint256) {
        return balanceOf[address(this)] - totalLocked;
    }

    /// @notice What claim() would pay right now with a server signature for `totalEarned` and the
    ///         payout choice `instant`: the difference to what was already claimed (80% of it when
    ///         instant, the rest is burned; 100% when locked, paid after 7 days), or 0 while claims
    ///         are paused, emission hasn't started, no signer is set, the difference doesn't fit in
    ///         today's remaining emission or the run-reward pool (claims are all-or-nothing), or a
    ///         locked claim would exceed MAX_ACTIVE_LOCKS (sixth audit, #2).
    function claimable(address account, uint256 totalEarned, bool instant) external view returns (uint256 amount) {
        if (claimsPaused || emissionStartDay == 0 || signer == address(0)) return 0;
        uint256 done = claimed[account];
        if (totalEarned <= done) return 0;
        amount = totalEarned - done;
        uint256 day = _today();
        uint256 limit = emissionOn(day);
        uint256 leftToday = limit > claimedOnDay[day] ? limit - claimedOnDay[day] : 0;
        if (amount > leftToday || amount > rewardsRemaining()) return 0;
        if (instant) return amount - amount * INSTANT_BURN_BPS / BPS;
        // claim() releases finished locks first, so only unfinished ones take a slot.
        Lock[] storage locks = _locks[account];
        uint256 active;
        for (uint256 i = _lockHead[account]; i < locks.length; i++) if (locks[i].unlockAt > block.timestamp) active++;
        if (active >= MAX_ACTIVE_LOCKS) return 0;
    }

    /// @notice Pay `account` its verified run earnings, either
    ///         • instant: 80% now, 20% burned — only the runner can choose this, or
    ///         • locked:  100% after 7 days — anyone may submit this for the runner.
    ///         The server signs the choice the runner made, so nobody else can switch it.
    ///         Any of the runner's locks that have finished are paid out in the same call.
    function claim(address account, uint256 totalEarned, uint256 deadline, uint8 v, bytes32 r, bytes32 s, bool instant) external {
        if (claimsPaused) revert ClaimsPaused();
        if (instant && msg.sender != account) revert OnlyRunnerCanClaimInstantly();
        if (emissionStartDay == 0) revert EmissionNotStarted();
        if (block.timestamp > deadline) revert Expired();
        if (account == address(0)) revert ZeroAddress();
        bytes32 digest = keccak256(abi.encodePacked(
            "\x19\x01", domainSeparator(), keccak256(abi.encode(CLAIM_TYPEHASH, account, totalEarned, deadline, instant))
        ));
        if (uint256(s) > HALF_ORDER || (v != 27 && v != 28)) revert BadSignature();
        address recovered = ecrecover(digest, v, r, s);
        if (recovered == address(0) || recovered != signer) revert BadSignature();

        uint256 done = claimed[account];
        if (totalEarned <= done) revert NothingToClaim();
        uint256 amount = totalEarned - done;
        uint256 day = _today();
        if (claimedOnDay[day] + amount > emissionOn(day)) revert DailyCapReached();
        if (rewardsRemaining() < amount) revert PoolEmpty();

        claimed[account] = totalEarned;
        claimedOnDay[day] += amount;
        totalClaimed += amount;
        emit Claimed(account, amount, totalEarned, instant);
        _releaseMatured(account, day);
        if (instant) {
            uint256 burnAmount = amount * INSTANT_BURN_BPS / BPS;
            _move(address(this), account, amount - burnAmount, day);
            _burnRewards(account, burnAmount);
        } else {
            Lock[] storage locks = _locks[account];
            if (locks.length - _lockHead[account] >= MAX_ACTIVE_LOCKS) revert TooManyLocks();
            uint256 unlockAt = block.timestamp + LOCK_PERIOD;
            locks.push(Lock(uint128(amount), uint64(unlockAt)));
            totalLocked += amount;
            emit RewardsLocked(account, amount, unlockAt);
        }
    }

    /// @notice Pay out `account`'s locks that have finished their 7 days (100%). Anyone may call.
    function release(address account) external returns (uint256 amount) {
        amount = _releaseMatured(account, _today());
        if (amount == 0) revert NothingToRelease();
    }

    /// @notice Take all your locked rewards now: finished locks pay 100%, unfinished ones
    ///         pay 80% and 20% is burned.
    function releaseEarly() external returns (uint256 paid) {
        uint256 day = _today();
        Lock[] storage locks = _locks[msg.sender];
        uint256 head = _lockHead[msg.sender];
        uint256 n = locks.length;
        uint256 total;
        uint256 burnAmount;
        for (uint256 i = head; i < n; i++) {
            Lock memory l = locks[i];
            total += l.amount;
            if (l.unlockAt > block.timestamp) burnAmount += uint256(l.amount) * INSTANT_BURN_BPS / BPS;
            delete locks[i];
        }
        if (total == 0) revert NothingToRelease();
        _lockHead[msg.sender] = n;
        totalLocked -= total;
        paid = total - burnAmount;
        _move(address(this), msg.sender, paid, day);
        emit RewardsReleased(msg.sender, paid);
        if (burnAmount > 0) _burnRewards(msg.sender, burnAmount);
    }

    /// @notice `account`'s locked run rewards: still locked, ready to release, next unlock time.
    function locksOf(address account) external view returns (uint256 locked, uint256 unlocked, uint256 nextUnlockAt, uint256 activeLocks) {
        Lock[] storage locks = _locks[account];
        uint256 n = locks.length;
        for (uint256 i = _lockHead[account]; i < n; i++) {
            Lock memory l = locks[i];
            if (l.unlockAt <= block.timestamp) unlocked += l.amount;
            else {
                locked += l.amount;
                if (nextUnlockAt == 0) nextUnlockAt = l.unlockAt;
            }
        }
        activeLocks = n - _lockHead[account];
    }

    /// @notice Most RUNNER the run-reward pool can pay out on `day` (0 before emission starts).
    ///         Exact for today and later days; earlier days follow the current schedule.
    function emissionOn(uint256 day) public view returns (uint256) {
        if (emissionStartDay == 0 || day < emissionStartDay) return 0;
        Schedule memory sch = _nextSchedule.fromDay != 0 && day >= _nextSchedule.fromDay ? _nextSchedule : _schedule;
        if (day < sch.fromDay) return 0;
        uint256 halvings = (day - sch.fromDay) / sch.halvingDays;
        uint256 amount = halvings >= 128 ? 0 : uint256(sch.dailyStart) >> halvings;
        return amount > sch.floor ? amount : sch.floor;
    }

    /// @notice The schedule in force and the one waiting to start (fromDay 0 = none).
    function emissionSchedule() external view returns (Schedule memory current, Schedule memory next) {
        // A pending schedule whose day has come is the one in force, even before it is promoted (fifth audit, #6).
        if (_nextSchedule.fromDay != 0 && _today() >= _nextSchedule.fromDay) return (_nextSchedule, next);
        return (_schedule, _nextSchedule);
    }

    /// @notice Today's run-reward emission and how much of it is still unclaimed.
    function emissionToday() external view returns (uint256 limit, uint256 remaining) {
        uint256 day = _today();
        limit = emissionOn(day);
        uint256 used = claimedOnDay[day];
        remaining = limit > used ? limit - used : 0;
    }

    function domainSeparator() public view returns (bytes32) {
        return block.chainid == _cachedChainId ? _cachedDomainSeparator : _buildDomainSeparator();
    }

    // ----------------------------------------------------------------- owner

    /// @notice Exclude another exchange pool from holder rewards (e.g. a RUNNER pool someone
    ///         created elsewhere), so its balance doesn't dilute holders. It changes nothing
    ///         about transfers. The rule (fifth audit, #4): a contract whose token0() and token1()
    ///         are two different contracts, one of them RUNNER, and whose factory() is a contract —
    ///         the shape of Uniswap v2/v3-style pools. An ordinary wallet can't qualify, but no
    ///         on-chain check can tell a pool from a contract built to look like one; this is an
    ///         owner power and can't be undone.
    function excludePool(address pool) external onlyOwner {
        if (pool.code.length == 0) revert NotAContract();
        if (excludedFromHolderRewards[pool]) revert AlreadyExcluded();
        address t0 = _poolToken(pool, 0x0dfe1681); // token0()
        address t1 = _poolToken(pool, 0xd21220a7); // token1()
        address other = t0 == address(this) ? t1 : t1 == address(this) ? t0 : address(0);
        if (other == address(0) || other == address(this) || other.code.length == 0) revert NotAPool();
        if (_poolToken(pool, 0xc45a0155).code.length == 0) revert NotAPool(); // factory()
        uint256 today = _today();
        _startDay(today);
        _exclude(pool, today);
        emit PoolExcluded(pool);
    }

    function setProtocolWallet(address wallet) external onlyOwner {
        if (wallet == address(0)) revert ZeroAddress();
        // Swept IMD would stay here (re-booked), be skimmable in the PoolManager, or stuck in the hook (fourth audit, #2).
        if (wallet == address(this) || wallet == poolManager || wallet == hook) revert BadAddress();
        protocolWallet = wallet;
        emit ProtocolWalletChanged(wallet);
    }

    /// @notice Set the RUNNER server's signing address. Zero disables run-reward claims.
    function setSigner(address newSigner) external onlyOwner {
        signer = newSigner;
        emit SignerChanged(newSigner);
    }

    function setClaimsPaused(bool paused_) external onlyOwner {
        claimsPaused = paused_;
        emit ClaimsPausedChanged(paused_);
    }

    /// @notice Start the run-reward emission today with the current schedule. Only once.
    function startEmission() external onlyOwner {
        if (emissionStartDay != 0) revert AlreadyStarted();
        uint256 today = _today();
        emissionStartDay = today;
        _schedule.fromDay = uint32(today);
        emit EmissionStarted(today);
    }

    /// @notice Set a new emission schedule: `dailyStart` RUNNER/day, halving every
    ///         `halvingDays`, never below `floor`. Before emission starts it replaces the
    ///         launch schedule; after, it begins (with a fresh halving clock) the next UTC day.
    function setEmissionSchedule(uint256 dailyStart, uint256 halvingDays, uint256 floor) external onlyOwner {
        if (dailyStart > MAX_DAILY_EMISSION || floor > dailyStart || halvingDays < MIN_HALVING_DAYS || halvingDays > MAX_HALVING_DAYS) revert BadSchedule();
        if (emissionStartDay == 0) {
            _schedule = Schedule(uint128(dailyStart), uint128(floor), uint32(halvingDays), 0);
            emit EmissionScheduleSet(dailyStart, halvingDays, floor, 0);
            return;
        }
        uint256 today = _today();
        if (_nextSchedule.fromDay != 0 && today >= _nextSchedule.fromDay) _schedule = _nextSchedule; // promote
        _nextSchedule = Schedule(uint128(dailyStart), uint128(floor), uint32(halvingDays), uint32(today + 1));
        emit EmissionScheduleSet(dailyStart, halvingDays, floor, today + 1);
    }

    /// @notice Step 1 of 2: propose a new owner (address(0) cancels a pending proposal).
    ///         Nothing changes until the proposed owner calls acceptOwnership().
    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner, newOwner);
    }

    /// @notice Step 2 of 2: the proposed owner takes over.
    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
    }

    // ----------------------------------------------------------------- internals

    function _today() private view returns (uint256) {
        return block.timestamp / 1 days;
    }

    /// Reads token0()/token1() from a pool without trusting it to behave (zero on failure).
    function _poolToken(address pool, bytes4 selector) private view returns (address token) {
        (bool ok, bytes memory ret) = pool.staticcall(abi.encodeWithSelector(selector));
        if (ok && ret.length == 32) token = abi.decode(ret, (address));
    }

    function _eligible(uint256 balance) private pure returns (uint256) {
        return balance >= MIN_HOLDING ? balance : 0;
    }

    /// First call on a day freezes that day's share total at the eligible supply, which is
    /// unchanged since the day began because every balance change calls this first.
    function _startDay(uint256 today) private {
        Day storage d = _days[today];
        if (!d.started) {
            d.started = true;
            d.shares = eligibleSupply;
        }
    }

    function _holderShareOf(address holder, uint256 day) private view returns (uint256) {
        Day storage d = _days[day];
        if (d.rewards == 0 || d.shares == 0) return 0;
        uint256 bal = eligibleBalanceOn(holder, day);
        return bal == 0 ? 0 : uint256(d.rewards) * bal / d.shares;
    }

    function _transfer(address from, address to, uint256 value) private {
        if (to == address(0) || from == address(0)) revert ZeroAddress(); // no forged "mint" events (third audit, #5)
        _move(from, to, value, _today());
    }

    /// Moves tokens and keeps holder checkpoints up to date.
    function _move(address from, address to, uint256 value, uint256 today) private {
        uint256 fromBal = balanceOf[from];
        if (fromBal < value) revert InsufficientBalance();
        if (from == to) { // balance unchanged, so the day's lowest balance must not change either
            _startDay(today);
            emit Transfer(from, to, value);
            return;
        }
        unchecked { balanceOf[from] = fromBal - value; }
        _track(from, fromBal, fromBal - value, today);
        uint256 toBal = balanceOf[to];
        balanceOf[to] = toBal + value;
        _track(to, toBal, toBal + value, today);
        emit Transfer(from, to, value);
    }

    /// Updates the eligible supply, the wallet's checkpoint for today and today's share total.
    function _track(address account, uint256 oldBal, uint256 newBal, uint256 today) private {
        _startDay(today); // before eligibleSupply changes, on every path (claims included)
        if (excludedFromHolderRewards[account] || oldBal == newBal) return;
        eligibleSupply = eligibleSupply - _eligible(oldBal) + _eligible(newBal);

        Checkpoint[] storage cps = _checkpoints[account];
        uint256 n = cps.length;
        uint256 oldMin;
        uint256 newMin;
        if (n > 0 && cps[n - 1].day == today) {
            Checkpoint storage cp = cps[n - 1];
            oldMin = cp.minBalance;
            newMin = newBal < oldMin ? newBal : oldMin;
            cp.minBalance = uint112(newMin);
            cp.endBalance = uint112(newBal);
        } else {
            oldMin = oldBal;                        // balance held since the day began
            newMin = newBal < oldBal ? newBal : oldBal;
            cps.push(Checkpoint(uint32(today), uint112(newMin), uint112(newBal)));
        }
        uint256 drop = _eligible(oldMin) - _eligible(newMin);
        if (drop > 0) _days[today].shares -= drop;
    }

    /// Removes a wallet from holder rewards. eligibleBalanceOn() then reads 0 for every day,
    /// so its weight also leaves the share totals of the days still claimable that nobody has
    /// been paid from yet — otherwise its slice could be claimed by nobody and every other
    /// holder would be diluted. A day someone was already paid from keeps its total, so every
    /// holder of that day is paid at the same rate and the day can never pay out more than it
    /// received (second IMD audit, finding 1); the excluded wallet's slice of such a day goes to
    /// the protocol wallet when the day is swept.
    function _exclude(address account, uint256 today) private {
        if (excludedFromHolderRewards[account]) return;
        for (uint256 d = today > CLAIM_WINDOW_DAYS ? today - CLAIM_WINDOW_DAYS : 0; d < today; d++) {
            Day storage past = _days[d];
            if (!past.started || past.paidOut > 0) continue;
            uint256 w = eligibleBalanceOn(account, d);
            past.shares -= w < past.shares ? w : past.shares;
        }
        uint256 bal = balanceOf[account];
        Checkpoint[] storage cps = _checkpoints[account];
        uint256 n = cps.length;
        uint256 todayCounted = n > 0 && cps[n - 1].day == today ? cps[n - 1].minBalance : bal;
        _days[today].shares -= _eligible(todayCounted);
        eligibleSupply -= _eligible(bal);
        excludedFromHolderRewards[account] = true;
    }

    function _buildDomainSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name)), keccak256("1"), block.chainid, address(this)));
    }

    function _spendAllowance(address from, uint256 value) private {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            if (allowed < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = allowed - value; }
        }
    }

    /// Constructor only: credits an opening balance as if held since the day began.
    function _mintAtStart(address to, uint256 value, uint256 today) private {
        totalSupply += value;
        uint256 bal = balanceOf[to];
        uint256 newBal = bal + value;
        balanceOf[to] = newBal;
        emit Transfer(address(0), to, value);
        if (excludedFromHolderRewards[to]) return;
        eligibleSupply = eligibleSupply - _eligible(bal) + _eligible(newBal);
        Checkpoint[] storage cps = _checkpoints[to];
        if (cps.length > 0) cps.pop(); // same wallet given two allocations
        cps.push(Checkpoint(uint32(today), uint112(newBal), uint112(newBal)));
    }

    function _mint(address to, uint256 value, uint256 today) private {
        totalSupply += value;
        uint256 bal = balanceOf[to];
        balanceOf[to] = bal + value;
        _track(to, bal, bal + value, today);
        emit Transfer(address(0), to, value);
    }

    /// Pays out finished locks (they form a prefix: every lock lasts the same 7 days).
    function _releaseMatured(address account, uint256 day) private returns (uint256 amount) {
        Lock[] storage locks = _locks[account];
        uint256 head = _lockHead[account];
        uint256 n = locks.length;
        while (head < n && locks[head].unlockAt <= block.timestamp) {
            amount += locks[head].amount;
            delete locks[head];
            head++;
        }
        if (amount == 0) return 0;
        _lockHead[account] = head;
        totalLocked -= amount;
        _move(address(this), account, amount, day);
        emit RewardsReleased(account, amount);
    }

    /// Burns run rewards from the pool held by this contract (instant claims, early releases).
    function _burnRewards(address account, uint256 amount) private {
        if (amount == 0) return;
        totalBurnedInstant += amount;
        _burn(address(this), amount);
        emit RewardsBurned(account, amount);
    }

    function _rewardBalance() private view returns (uint256) {
        (bool ok, bytes memory ret) = rewardToken.staticcall(abi.encodeWithSelector(0x70a08231, address(this))); // balanceOf(address)
        if (!ok || ret.length < 32) revert TransferFailed();
        return abi.decode(ret, (uint256));
    }

    function _sendReward(address to, uint256 amount) private {
        (bool ok, bytes memory ret) = rewardToken.call(abi.encodeWithSelector(0xa9059cbb, to, amount)); // transfer(address,uint256)
        if (!ok || (ret.length != 0 && !abi.decode(ret, (bool)))) revert TransferFailed();
    }

    function _burn(address from, uint256 value) private {
        if (from == address(0)) revert ZeroAddress(); // no forged events from the zero address (fourth audit, #9)
        uint256 bal = balanceOf[from];
        if (bal < value) revert InsufficientBalance();
        uint256 today = _today();
        _startDay(today);
        unchecked {
            balanceOf[from] = bal - value;
            totalSupply -= value;
        }
        _track(from, bal, bal - value, today);
        emit Transfer(from, address(0), value);
    }
}
